INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M37-X001', 'HDSAT-RW-M37-X001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
Plate tectonics (from Latin tectonicus, from Ancient Greek τεκτονικός (tektonikós) ''pertaining to building'') is the scientific theory that Earth''s lithosphere comprises a number of large tectonic plates, which have been slowly moving since 3–4 billion years ago. The model builds on the concept of continental drift, an idea developed during the first decades of the 20th century.

Text 2
A volcano is a vent or fissure in the crust of a planetary-mass object that allows hot lava, volcanic ash, and gases to escape from a magma chamber below the surface. On Earth, volcanoes are most often found where tectonic plates are diverging or converging, and because most of Earth''s plate boundaries are underwater, most volcanoes are found underwater.', 'Based on the texts, how would the author of Text 2 most likely respond to the argument in Text 1?', '[{"id": "A", "text": "By claiming that volcanoes occur only on dry land."}, {"id": "B", "text": "By rejecting plate tectonics in favor of the older idea of continental drift."}, {"id": "C", "text": "By arguing that Earth''s plates stopped moving billions of years ago."}, {"id": "D", "text": "By noting that volcanic activity is concentrated where the moving plates described in Text 1 diverge or converge."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Plate tectonics", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Plate_tectonics; Wikipedia, "Volcano", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Volcano', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M37-X001', 'D', ARRAY['D']::TEXT[], 'Text 1 explains that Earth''s lithosphere is divided into slowly moving plates, and Text 2 states that volcanoes are most often found where those plates diverge or converge. The second author would therefore connect volcanism to the plate boundaries Text 1 describes.', '{"B": "Text 2 relies on plate boundaries, not on replacing the theory.", "A": "Text 2 says most volcanoes are underwater.", "C": "Text 1 says the plates have moved for billions of years."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
