INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M37-X005', 'HDSAT-RW-M37-X005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
Artificial intelligence (AI) is the capability of computational systems to perform tasks typically associated with human intelligence, such as learning, reasoning, problem-solving, perception, and decision-making. It is also a field of research spanning computer science, engineering, and mathematics that develops and studies methods and software enabling machines to perceive their environment and use learning and intelligence to take actions that maximise their chances of achieving defined goals.

Text 2
Machine learning (ML) is a field of study in artificial intelligence concerned with the development and study of statistical algorithms that can learn from data and generalize to unseen data, and thus perform tasks without being explicitly programmed. Statistics and mathematical optimisation methods compose the foundations of machine learning.', 'Based on the texts, how would the author of Text 2 most likely respond to the argument in Text 1?', '[{"id": "A", "text": "By claiming that AI and machine learning are unrelated fields."}, {"id": "B", "text": "By clarifying that machine learning is a subfield of AI that develops statistical algorithms able to learn from data."}, {"id": "C", "text": "By arguing that machine learning has no connection to statistics."}, {"id": "D", "text": "By denying that AI involves learning or reasoning."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Artificial intelligence", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Artificial_intelligence; Wikipedia, "Machine learning", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Machine_learning', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M37-X005', 'B', ARRAY['B']::TEXT[], 'Text 1 describes AI broadly as a capability and a field of research. Text 2 identifies machine learning as a field of study within AI, built on statistical algorithms that learn from data, so its author would clarify that narrower relationship.', '{"D": "Text 1 explicitly lists learning and reasoning as AI tasks.", "C": "Text 2 says statistics compose machine learning''s foundations.", "A": "Text 2 defines ML as a field in AI."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M37-X006', 'HDSAT-RW-M37-X006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Medium', 'multiple_choice', 'Text 1
Artificial intelligence (AI) is the capability of computational systems to perform tasks typically associated with human intelligence, such as learning, reasoning, problem-solving, perception, and decision-making. It is also a field of research spanning computer science, engineering, and mathematics that develops and studies methods and software enabling machines to perceive their environment and use learning and intelligence to take actions that maximise their chances of achieving defined goals.

Text 2
Machine learning (ML) is a field of study in artificial intelligence concerned with the development and study of statistical algorithms that can learn from data and generalize to unseen data, and thus perform tasks without being explicitly programmed. Statistics and mathematical optimisation methods compose the foundations of machine learning.', 'Which choice best describes the relationship between the two texts?', '[{"id": "A", "text": "Text 2 narrows the broad field described in Text 1 to one of its approaches."}, {"id": "B", "text": "Text 2 argues that AI cannot perform cognitive tasks."}, {"id": "C", "text": "Text 2 rejects the definition offered in Text 1."}, {"id": "D", "text": "Text 2 describes the history of AI''s founding."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Artificial intelligence", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Artificial_intelligence; Wikipedia, "Machine learning", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Machine_learning', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M37-X006', 'A', ARRAY['A']::TEXT[], 'Text 1 defines AI as a broad capability and research field. Text 2 then describes machine learning as a field within AI, focused on statistical algorithms, so it narrows the earlier discussion to a particular approach.', '{"C": "Text 2 begins by placing itself inside AI.", "D": "Text 2 describes methods, not AI''s founding.", "B": "Text 2 assumes AI systems learn and generalize."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M37-X007', 'HDSAT-RW-M37-X007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Cross-Text Connections', 'Easy', 'multiple_choice', 'Text 1
The American Civil War (April 12, 1861 – May 26, 1865; also known by other names) was a civil war in the United States between the Union ("the North") and the Confederacy ("the South"), which was formed in 1861 by Southern states that had seceded from the Union to preserve slavery in the United States. The South saw slavery as threatened because of the election of Abraham Lincoln as president in 1860 and the growing abolitionist movement in the North.

Text 2
The Reconstruction era, often simply called Reconstruction, was a period in United States history that followed the American Civil War (1861–1865) and was dominated by the legal, social, and political challenges of the abolition of slavery and federal control over, and reintegration of, the former Confederate States into the United States. Three amendments were added to the United States Constitution to grant citizenship and equal civil rights to the newly freed slaves.', 'Based on the texts, how would the author of Text 2 most likely respond to the argument in Text 1?', '[{"id": "A", "text": "By denying that the Civil War took place."}, {"id": "B", "text": "By noting that the period after the war focused on abolishing slavery and reintegrating the former Confederate states."}, {"id": "C", "text": "By claiming that Reconstruction came before the Civil War."}, {"id": "D", "text": "By arguing that no constitutional amendments were adopted."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "American Civil War", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/American_Civil_War; Wikipedia, "Reconstruction era", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Reconstruction_era', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M37-X007', 'B', ARRAY['B']::TEXT[], 'Text 1 explains that the war was fought between the Union and the Confederacy over slavery. Text 2 describes the period that followed the war, when slavery was abolished and the former Confederate states were reintegrated, so its author would add that aftermath.', '{"A": "Text 2 dates itself after the Civil War.", "C": "Text 2 explicitly follows the war.", "D": "Text 2 says three amendments were added."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
